  if(f.field.startsWith('identity.')||f.field==='child.name')continue; // Identification never needed by the calculator.
  const definition=FIELD_BY_ID[f.field],checked=documentValue(f.valueType||definition?.type||'text',f.value);if(!checked.valid)throw new Error(f.label+': '+checked.reason);
  const value=checked.value,parent=Number(f.assignment||0),titleIndex=Number(f.title||0);if(titleIndex<0||titleIndex>3)throw new Error('Przypisz właściwy tytuł ubezpieczenia.');
  if(f.scope==='child'&&['childBirthDate','adoptionPlacement','birthWeight'].includes(f.field)){const index=Number(f.child||0);if(!Number.isInteger(index)||index<0||index>11)throw new Error('Wskaż właściwe dziecko.');while(out.formalCase.children.length<=index)out.formalCase.children.push({birthDate:'',placementDate:'',weight:null});out.formalCase.children[index][f.field==='childBirthDate'?'birthDate':f.field==='adoptionPlacement'?'placementDate':'weight']=value;if(index>0&&f.field!=='birthWeight'){provenance.push({field:f.field,documentId:f.documentId,page:f.page,method:f.method,child:index,confirmed:true});continue;}}
  const owner=out.parents[parent];owner.extraTitles??=[];while(titleIndex>owner.extraTitles.length)owner.extraTitles.push({...structuredClone(owner),extraTitles:[],coverage:'unknown',insuranceFrom:'',insuranceTo:'',basis:null,salary:null,history:[],debt:0,insuranceFacts:null});const title=titleIndex?owner.extraTitles[titleIndex-1]:owner;let target;
  if(['basis','salary'].includes(f.field)||f.field.startsWith('wage.')){const key=parent+'|'+titleIndex,modes=basisMethods.get(key)||new Set();modes.add(f.field.startsWith('wage.')?'history':f.field);basisMethods.set(key,modes);if(modes.size>1)throw new Error('Dla tej samej osoby i tytułu wybrano różne sposoby ustalenia podstawy. Pozostaw podstawę ustaloną przez płatnika albo wynagrodzenie / historię, zamiast zastępować je w kolejności plików.');}
  if(['employmentStart','employmentEnd','fteChangedAt'].includes(f.field)&&parent!==Number(primaryParent))throw new Error('Daty zatrudnienia w części formalnej muszą dotyczyć wybranej osoby wnioskującej. Pozostałe daty zachowaj w odrębnej sprawie.');
  if(f.field.startsWith('wage.')){if(!/^20\d{2}-(0[1-9]|1[0-2])$/.test(f.period||''))throw new Error('Przypisz miesiąc do wynagrodzenia.');const key=[parent,titleIndex,f.period].join('|');const row=wages.get(key)||{parent,titleIndex,month:f.period,gross:null,deducted:null,worked:null,scheduled:null,excused:true};row[f.field.slice(5)]=value;wages.set(key,row);}
  else if(parentFields.has(f.field)){target=definition?.target||f.field;set(title,target,value);if(f.field==='basis')title.basisMode='known';if(f.field==='salary')title.basisMode='salary';}
  else if(caseFields.has(f.field)){target=definition?.target||f.field;set(out,target,f.field==='schoolDelayed'?value==='yes':value);if(['eventDate','childBirthDate'].includes(f.field)){out.eventDate=value;out.childBirthDate=value;out.dateKind='actual';}if(f.field==='dueDate')out.dateKind='expected';if(f.field==='count'&&(value<1||value>12))throw new Error('Sprawdź liczbę dzieci.');if(f.field==='gestationWeek'&&(value<0||value>45)||f.field==='gestationDay'&&value>6)throw new Error('Sprawdź tydzień i dzień ciąży przy porodzie.');}
  else if(/^(sickness|care)\.(start|end|days|certificate|pregnant)$/.test(f.field)){const [kind,key]=f.field.split('.');if(key==='end')ranges.set(kind,value);else set(out,f.field,f.field==='sickness.pregnant'?value==='yes':value);if(kind==='care')out.care.parent=parent;}
  else if(/^hospital\.(start|end)$/.test(f.field)){const key='hospital|'+(f.child||0),range=ranges.get(key)||{child:Number(f.child||0),start:'',end:''};range[f.field.split('.')[1]]=value;ranges.set(key,range);}
